import sys

def gen_brute(n):
    from itertools import product
    res = []
    for bits in product('()', repeat=2 * n):
        s = ''.join(bits)
        bal = 0
        ok = True
        for ch in s:
            bal += 1 if ch == '(' else -1
            if bal < 0:
                ok = False
                break
        if ok and bal == 0:
            res.append(s)
    return sorted(set(res))

if __name__ == '__main__':
    n = int(sys.stdin.read().strip())
    for s in gen_brute(n):
        print(s)

import sys

def gen_opt(n):
    res = []
    def dfs(cur, left, right):
        if len(cur) == 2 * n:
            res.append(cur)
            return
        if left < n:
            dfs(cur + '(', left + 1, right)
        if right < left:
            dfs(cur + ')', left, right + 1)
    dfs('', 0, 0)
    return res

if __name__ == '__main__':
    n = int(sys.stdin.read().strip())
    for s in gen_opt(n):
        print(s)

